from multiprocessing import Queue

from .writer import FileWriter


class SyslogLogger:
    """Class responsible for consuming queue data, cleaning it and writing it to log file.

    :param queue: Queue to consume data from.
    :type queue: Queue
    :param log_dir: Directory in which log files will be stored.
    :type log_dir: str
    :param log_name: Name of the log file.
    :type log_name: str
    :param file_size_limit: Limit of log file size in bytes. If 0, log file will not be split.
    :type file_limit: int
    :param add_line_number: Flag indicating whether line numbers should be added to log entries, defaults to False
    :type add_line_number: bool, optional
    """

    def __init__(
        self,
        queue: Queue,
        log_dir: str,
        log_name: str,
        file_size_limit: int,
        add_line_number: bool = False,
    ) -> None:
        self.queue = queue
        self.file_limit = file_size_limit
        self.add_line_number = add_line_number
        self._writer = FileWriter(log_dir, log_name, file_size_limit, add_line_number)

    @staticmethod
    def _decode_data(data: bytes, addr: tuple) -> str:
        data = data.decode("utf-8", errors="ignore")
        trace = "[{}] {}".format(addr[0], data.rstrip("\0"))
        trace = trace.rstrip("\r\n")
        trace = trace.replace("\n", f"\n[{addr[0]}] ")
        return trace

    def decode_and_write(self, data: bytes):
        message = self._decode_data(data[0], data[1])
        self._writer.write(message)

    def clean_log_file(self):
        self._writer.clean_log()

    def run(self):
        while True:
            queue_item = self.queue.get()
            if queue_item is None:
                break
            self.decode_and_write(queue_item)
